$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(-not(Test-Command winget)){throw 'winget no disponible.'};foreach($id in 'Kitware.CMake','Ninja-build.Ninja','Git.Git'){if(-not(Test-Command ($id.Split('.')[0]))){& winget install --id $id --silent --accept-package-agreements --accept-source-agreements}};$machine=[Environment]::GetEnvironmentVariable('PATH','Machine');$user=[Environment]::GetEnvironmentVariable('PATH','User');$env:PATH="$machine;$user";foreach($c in 'cmake','ninja','git'){if(-not(Test-Command $c)){throw "$c no disponible"}};Write-Ok 'Dependencias C++ base listas';if(-not(Test-Command vcpkg)){Write-Warn 'vcpkg no instalado. Paho/SQLite/OpenSSL se gestionan mediante vcpkg cuando el Edge Gateway Windows lo requiera.'}
